async def faq_agent(state: AgentState) -> AgentState:
    query = state['messages'][-1]['content']

    # Semantic search in FAQ database
    relevant_faqs = await search_faqs(query, top_k=3)

    if not relevant_faqs or relevant_faqs[0].score < 0.7:
        return {**state, 'current_agent': 'tech', 'intent': 'needs_escalation'}

    context = '\n'.join([f.answer for f in relevant_faqs])
    response = await llm.ainvoke(FAQ_PROMPT.format(
        question=query, context=context
    ))

    return {**state, 'messages': state['messages'] + [{'role': 'assistant', 'content': response}]}
